management-password-rotated.command:
set -u
code="$(curl -s -o /dev/null -w '%{http_code}' --max-time 10 -X POST \
  -H 'Content-Type: application/json' \
  -d '{"password":"CHANGEME"}' \
  http://127.0.0.1:20128/api/auth/login 2>/dev/null)"
[ -n "$code" ] || code=000
case "$code" in
  401) echo "DEFAULT-PASSWORD-REJECTED-OK code=$code" ;;
  000) echo 'NON_VERIFIED gateway unreachable at 127.0.0.1:20128 -- an unreachable check fails, never passes'; exit 1 ;;
  200) echo "DEFAULT-PASSWORD-STILL-ACTIVE code=$code -- CHANGEME was accepted"; exit 1 ;;
  *) echo "NON_VERIFIED unexpected http_code=$code -- fails closed rather than guessing what it means"; exit 1 ;;
esac
